  1	/**
  2	 * Session-Change-Tracker: Verfolgt alle Dateiänderungen während einer Session.
  3	 * Rekonstruiert State aus Session-Entries beim Branch-Wechsel.
  4	 */
  5	import type { ExtensionContext } from "@earendil-works/pi-coding-agent";
  6	import type { DiffHunk, DiffStats, SessionChange } from "./types.ts";
  7	
  8	export class ChangeTracker {
  9	  private changes = new Map<string, SessionChange[]>();
 10	  private _initialized = false;
 11	
 12	  /** Alle geänderten Dateipfade mit letztem Change. */
 13	  get changedFiles(): SessionChange[] {
 14	    const result = this.summarizeChanges().changedFiles;
 15	    // Neueste zuerst
 16	    return result.sort((a, b) => b.timestamp - a.timestamp);
 17	  }
 18	
 19	  /** Gesamtanzahl Änderungen. */
 20	  get totalChanges(): number {
 21	    return this.summarizeChanges().totalChanges;
 22	  }
 23	
 24	  private summarizeChanges(): {
 25	    changedFiles: SessionChange[];
 26	    totalChanges: number;
 27	  } {
 28	    const changedFiles: SessionChange[] = [];
 29	    let totalChanges = 0;
 30	
 31	    for (const fileChanges of this.changes.values()) {
 32	      totalChanges += fileChanges.length;
 33	      if (fileChanges.length > 0) {
 34	        changedFiles.push(fileChanges[fileChanges.length - 1]!);
 35	      }
 36	    }
 37	
 38	    return { changedFiles, totalChanges };
 39	  }
 40	
 41	  /** Fügt eine Änderung hinzu. */
 42	  recordChange(
 43	    path: string,
 44	    toolName: string,
 45	    stats: DiffStats,
 46	    hunks: DiffHunk[],
 47	    timestamp = Date.now(),
 48	  ): void {
 49	    const entry: SessionChange = {
 50	      path,
 51	      toolName,
 52	      timestamp,
 53	      stats,
 54	      hunks,
 55	    };
 56	
 57	    const existing = this.changes.get(path);
 58	    if (existing) {
 59	      existing.push(entry);
 60	    } else {
 61	      this.changes.set(path, [entry]);
 62	    }
 63	  }
 64	
 65	  /** Gibt alle Änderungen für eine Datei zurück. */
 66	  getChangesForFile(path: string): SessionChange[] {
 67	    return this.changes.get(path) ?? [];
 68	  }
 69	
 70	  /** Setzt den Tracker zurück. */
 71	  reset(): void {
 72	    this.changes.clear();
 73	    this._initialized = false;
 74	  }
 75	
 76	  /** Initialisiert den Tracker durch Rekonstruktion aus Session-Entries. */
 77	  reconstructFromSession(ctx: ExtensionContext): void {
 78	    this.reset();
 79	
 80	    for (const entry of ctx.sessionManager.getBranch()) {
 81	      if (entry.type !== "custom") continue;
 82	      if (entry.customType !== "diff-view") continue;
 83	
 84	      const data = entry.data as {
 85	        path: string;
 86	        toolName?: string;
 87	        stats?: DiffStats;
 88	        hunks?: DiffHunk[];
 89	        timestamp?: number;
 90	      } | undefined;
 91	
 92	      if (data?.path && data.stats && data.hunks) {
 93	        this.recordChange(
 94	          data.path,
 95	          data.toolName ?? "unknown",
 96	          data.stats,
 97	          data.hunks,
 98	          data.timestamp,
 99	        );
100	      }

